import sys

d = sys.stdin.read().split()
n, k = int(d[0]), int(d[1])
a = [int(x) for x in d[2:2 + n]]
res = 0
for i in range(n):
    for j in range(i + 1, n):
        if a[i] == a[j] and j - i <= k:
            res += 1
print(res)

